/**
 * Async Standup — tool-local actions.
 *
 * Category: Ceremonies (squad S3 — async-first daily standup)
 * Tool:     Per-member daily updates with an auto-generated digest
 *
 * Agent surface: tool.async_standup.*
 * Backing CRUD : workspace.async_update.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * Posting an update is plain create via workspace.async_update.create; this
 * file adds the two read verbs an agent actually reaches for:
 *
 *   1. list_state — counts + today's blocker rollup + a per-day histogram
 *                   so an agent can answer "who's posted / who's blocked?".
 *   2. digest     — the tool's signature output: a grouped-by-member
 *                   markdown digest for a given day (defaults to today),
 *                   ready to paste into Slack/email.
 *
 * Entity kind is "workspace:asyncUpdate" (camelCase via kindFromToolId),
 * matching the browser sync engine so MCP-posted updates round-trip.
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities } from "../server-store";
import type { AsyncUpdate } from "@/lib/stores/workspace-types";

const KIND_ASYNC = "workspace:asyncUpdate";

const ws = () => useWorkspaceStore.getState();

/** Server-side "today" (UTC). The browser tool uses the local day; an MCP
 *  agent has no locale, so UTC is the least-surprising default. Callers can
 *  pass an explicit `date` to digest any specific day. */
function todayUTC(): string {
  return new Date().toISOString().slice(0, 10);
}

/** Flatten newlines so a user-typed paragraph stays on one markdown bullet. */
function singleLine(s: string | undefined): string {
  return (s ?? "").replace(/\r?\n/g, " ").trim();
}

/** Grouped-by-member markdown digest for a single day, with a blockers
 *  rollup at the top. Mirrors the in-app digest so the agent and the UI
 *  produce the same artifact. */
function buildDigest(updates: AsyncUpdate[], date: string): string {
  const days = updates.filter((u) => u.date === date);
  if (days.length === 0) return `# Async Standup — ${date}\n\nNo updates posted.`;
  const lines: string[] = [`# Async Standup — ${date}`, ""];
  const blocked = days.filter((u) => singleLine(u.blockers).length > 0);
  if (blocked.length > 0) {
    lines.push("## Blockers");
    for (const u of blocked) lines.push(`- **${u.member}**: ${singleLine(u.blockers)}`);
    lines.push("");
  }
  const byMember = new Map<string, AsyncUpdate[]>();
  for (const u of days) {
    const list = byMember.get(u.member) ?? [];
    list.push(u);
    byMember.set(u.member, list);
  }
  for (const [member, ms] of Array.from(byMember.entries())) {
    lines.push(`## ${member}`);
    for (const u of ms) {
      if (singleLine(u.yesterday)) lines.push(`- **Yesterday**: ${singleLine(u.yesterday)}`);
      if (singleLine(u.today)) lines.push(`- **Today**: ${singleLine(u.today)}`);
      if (singleLine(u.blockers)) lines.push(`- **Blockers**: ${singleLine(u.blockers)}`);
      if (singleLine(u.description)) lines.push(`- ${singleLine(u.description)}`);
    }
    lines.push("");
  }
  return lines.join("\n").trimEnd();
}

/** Build the {total, today, todaysCount, todaysBlockers, byDate} response.
 *  Shared by the browser + MCP paths so both return an identical shape. */
function listState(items: AsyncUpdate[]) {
  const today = todayUTC();
  const todays = items.filter((u) => u.date === today);
  const todaysBlockers = todays.filter((u) => singleLine(u.blockers).length > 0);
  const counts = new Map<string, number>();
  for (const u of items) counts.set(u.date, (counts.get(u.date) ?? 0) + 1);
  const byDate = Array.from(counts.entries())
    .map(([date, count]) => ({ date, count }))
    .sort((a, b) => (a.date < b.date ? 1 : -1)); // newest day first
  return { total: items.length, today, todaysCount: todays.length, todaysBlockers, byDate };
}

// ──────── tool.async_standup.list_state ────────
registry.register({
  id: "tool.async_standup.list_state",
  toolId: "tool.async_standup",
  name: "list_state",
  category: "read",
  description:
    "Summarise async standup activity. Returns {total, today (UTC YYYY-MM-DD), todaysCount, todaysBlockers: AsyncUpdate[], byDate: {date, count}[] (newest day first)}.",
  paramsSchema: z.object({}),
  handler: async () => listState(ws().asyncUpdates ?? []),
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<AsyncUpdate>(ctx.userId, KIND_ASYNC);
    return listState(items);
  },
});

// ──────── tool.async_standup.digest ────────
registry.register({
  id: "tool.async_standup.digest",
  toolId: "tool.async_standup",
  name: "digest",
  category: "read",
  description:
    "Render a grouped-by-member markdown digest for one day (defaults to today, UTC). Returns {date, markdown, updateCount, blockerCount}.",
  paramsSchema: z.object({
    date: z.string().optional().describe("Day to digest, YYYY-MM-DD. Defaults to today (UTC)."),
  }),
  handler: async (params) => {
    const date = params.date ?? todayUTC();
    const items = ws().asyncUpdates ?? [];
    const day = items.filter((u) => u.date === date);
    return {
      date,
      markdown: buildDigest(items, date),
      updateCount: day.length,
      blockerCount: day.filter((u) => singleLine(u.blockers).length > 0).length,
    };
  },
  mcpHandler: async (params, ctx) => {
    const date = params.date ?? todayUTC();
    const items = await serverListEntities<AsyncUpdate>(ctx.userId, KIND_ASYNC);
    const day = items.filter((u) => u.date === date);
    return {
      date,
      markdown: buildDigest(items, date),
      updateCount: day.length,
      blockerCount: day.filter((u) => singleLine(u.blockers).length > 0).length,
    };
  },
});
